import{CWA_BASE,CWA_FILES,normalizeStations,normalizeForecast,normalizeWarnings}from'./weather-core.mjs';
export async function loadCwaWeather(fetcher=fetch){const result=await Promise.allSettled(CWA_FILES.map(async p=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetcher(CWA_BASE+p,{signal:controller.signal,headers:{Accept:'application/json'},cache:p.startsWith('Warning/')?'no-store':'default',cf:{cacheTtl:p.startsWith('Warning/')?0:300,cacheEverything:!p.startsWith('Warning/')}});if(!r.ok)throw Error('上游服務 '+r.status);const text=await r.text();if(text.length>6000000)throw Error('資料過大');return JSON.parse(text)}finally{clearTimeout(timer)}}));
 const stations=new Map(),errors=[];let hourly=null,weekly=null,warnings=null;const observations=[];result.forEach((r,i)=>{try{if(r.status!=='fulfilled')throw Error();if(i<2){for(const s of normalizeStations(r.value,true)){observations.push(s);if(s.temp===null)continue;const prev=stations.get(s.id);if(!prev||Date.parse(s.time)>=Date.parse(prev.time))stations.set(s.id,s)}}else if(i===2)hourly=normalizeForecast(r.value);else if(i===3)weekly=normalizeForecast(r.value);else warnings=normalizeWarnings(r.value)}catch{errors.push(CWA_FILES[i].split('/').pop())}});if(!stations.size&&!hourly&&!weekly)throw Error('無法取得中央氣象署資料');return{source:'中央氣象署',retrievedAt:new Date().toISOString(),stations:[...stations.values()],observations,hourly,weekly,warnings,unavailable:errors}}
export async function loadCwaWarnings(fetcher=fetch){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const r=await fetcher(CWA_BASE+'Warning/W-C0033-002.json',{signal:controller.signal,cache:'no-store',cf:{cacheTtl:0,cacheEverything:false}});if(!r.ok)throw Error('警特報連線失敗');const text=await r.text();if(text.length>2000000)throw Error('警特報資料過大');return normalizeWarnings(JSON.parse(text))}finally{clearTimeout(timer)}}
